// --- SOUND SYNTHESIS (Web Audio API) ---
class SoundFX {
  constructor() {
    this.ctx = null;
    this.muted = false;
  }
  init() {
    if (!this.ctx && typeof window !== 'undefined') {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) this.ctx = new AudioCtx();
    }
  }
  playTone(freq, type = 'sine', duration = 0.15, delay = 0, vol = 0.12) {
    if (this.muted) return;
    try {
      this.init();
      if (!this.ctx) return;
      if (this.ctx.state === 'suspended') this.ctx.resume();
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, this.ctx.currentTime + delay);
      gain.gain.setValueAtTime(vol, this.ctx.currentTime + delay);
      gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + delay + duration);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start(this.ctx.currentTime + delay);
      osc.stop(this.ctx.currentTime + delay + duration);
    } catch (e) {
      // Ignore audio errors
    }
  }
  xpGain() {
    this.playTone(587.33, 'triangle', 0.12, 0, 0.1);
    this.playTone(880, 'triangle', 0.18, 0.08, 0.12);
  }
  coinSpend() {
    this.playTone(987.77, 'sine', 0.09, 0, 0.12);
    this.playTone(1318.51, 'sine', 0.16, 0.07, 0.12);
  }
  levelUp() {
    const notes = [523.25, 659.25, 783.99, 1046.5];
    notes.forEach((n, i) => this.playTone(n, 'square', 0.22, i * 0.09, 0.1));
  }
  puzzleCorrect() {
    this.playTone(659.25, 'sine', 0.12, 0, 0.12);
    this.playTone(783.99, 'sine', 0.12, 0.1, 0.12);
    this.playTone(1046.5, 'triangle', 0.28, 0.2, 0.15);
  }
  puzzleWrong() {
    this.playTone(220, 'sawtooth', 0.18, 0, 0.1);
    this.playTone(185, 'sawtooth', 0.25, 0.12, 0.1);
  }
}

