// --- DYNAMIC QUEST SCALING ENGINE BASED ON HIGHEST CLASS LEVEL ACHIEVED ---
// Even if the user equips a Lv.1 class, quests scale to their highest unlocked class rank across all 4 branches!
function getScaledDailyQuests(highestClassRank, currentProgressMap = {}) {
  const tierIndex = Math.max(0, highestClassRank - 1); // 0 .. 9
  const readCyclesReq = 1 + Math.floor(tierIndex / 3); // Lv1-3: 1 cycle (15m), Lv4-6: 2 cycles (30m), Lv7-9: 3 cycles (45m), Lv10: 4 cycles (60m)
  const waterLiters = (2.0 + tierIndex * 0.2).toFixed(1); // Lv1: 2.0L, Lv3: 2.4L, Lv5: 2.8L ...
  const gymMins = 45 + tierIndex * 5; // Lv1: 45m, Lv3: 55m, Lv5: 65m ...
  const stepsReq = 6000 + tierIndex * 1000; // Lv1: 6000, Lv3: 8000, Lv5: 10000 ...
  const pushupsReps = 20 + tierIndex * 10; // Lv1: 20, Lv3: 40, Lv5: 60 ...

  const baseQuests = [
    {
      id: 'q1',
      title: `Leer ${readCyclesReq * 15} min continuos (${readCyclesReq} ciclo${readCyclesReq > 1 ? 's' : ''} de 15m) en el Grimorio PDF`,
      skill: 'int',
      xp: 30 + tierIndex * 5,
      coins: 3,
      mode: 'auto',
      autoTriggerLabel: 'Se completa automáticamente al cerrar ciclos de 15m en Libros PDF',
      goal: readCyclesReq,
      unit: 'ciclo(s) 15m'
    },
    {
      id: 'q2',
      title: `Hidratación Real: Tomar ${waterLiters}L de agua pura durante el día`,
      skill: 'vit',
      xp: 25 + tierIndex * 4,
      coins: 2,
      mode: 'manual',
      goal: 1,
      unit: `${waterLiters}L agua`
    },
    {
      id: 'q3',
      title: `Entrenar ${gymMins} min en tu Gimnasio o Parque (Detección GPS)`,
      skill: 'str',
      xp: 45 + tierIndex * 6,
      coins: 4,
      mode: 'auto',
      autoTriggerLabel: 'Se completa automáticamente por GPS en Auto-Sync o Entreno Activo',
      goal: 1,
      unit: 'sesión GPS'
    },
    {
      id: 'q4',
      title: highestClassRank >= 3
        ? `Socializar activamente: Conectar con ${1 + Math.floor(tierIndex / 2)} personas en comunidad/voz o charla profunda`
        : 'Hablar en comunidad / Discord o iniciar una charla genuina con alguien',
      skill: 'cha',
      xp: 35 + tierIndex * 5,
      coins: 3,
      mode: 'manual',
      goal: 1,
      unit: 'interacción'
    },
    {
      id: 'q5',
      title: `Caminar ${stepsReq.toLocaleString()} pasos diarios (Sincronización Podómetro)`,
      skill: 'vit',
      xp: 35 + tierIndex * 5,
      coins: 3,
      mode: 'auto',
      autoTriggerLabel: 'Se completa automáticamente cuando el podómetro alcanza la meta',
      goal: stepsReq,
      unit: 'pasos'
    },
    {
      id: 'q6',
      title: `Activación Física en Casa: ${pushupsReps} flexiones/sentadillas y ordenar tu habitación`,
      skill: 'str',
      xp: 30 + tierIndex * 4,
      coins: 2,
      mode: 'manual',
      goal: 1,
      unit: 'rutina'
    }
  ];

  return baseQuests.map(q => {
    const prev = currentProgressMap[q.id] || { progress: q.id === 'q5' ? 4500 : 0, completed: false };
    const prog = Math.min(q.goal, prev.progress);
    return {
      ...q,
      progress: prog,
      completed: prev.completed || prog >= q.goal
    };
  });
}

function getScaledWeeklyQuests(highestClassRank, currentProgressMap = {}) {
  const tierIndex = Math.max(0, highestClassRank - 1);
  const cleanDaysReq = Math.min(7, 4 + Math.floor(tierIndex / 2)); // 4 to 7 days
  const gymDaysReq = Math.min(6, 3 + Math.floor(tierIndex / 2)); // 3 to 6 days
  const readBlocksReq = 4 + tierIndex * 2; // 4, 6, 8, 10...

  const baseWeekly = [
    {
      id: 'wq1',
      title: `Escudo Férreo: ${cleanDaysReq} días de la semana sin exceder el límite en Apps de Distracción`,
      skill: 'wil',
      xp: 130 + tierIndex * 15,
      coins: 12,
      mode: 'auto',
      autoTriggerLabel: 'Automática vía sensor de Tiempo en Pantalla (Escudo Anti-Distracciones)',
      goal: cleanDaysReq,
      unit: 'días limpios'
    },
    {
      id: 'wq2',
      title: `Templanza Estoica: ${cleanDaysReq} días despertando al primer timbre sin posponer la alarma`,
      skill: 'wil',
      xp: 145 + tierIndex * 15,
      coins: 14,
      mode: 'manual',
      goal: cleanDaysReq,
      unit: 'días'
    },
    {
      id: 'wq3',
      title: `Constancia de Acero: ${gymDaysReq} entrenamientos de Fuerza detectados por GPS en la semana`,
      skill: 'wil',
      xp: 150 + tierIndex * 15,
      coins: 14,
      mode: 'auto',
      autoTriggerLabel: 'Automática al registrar estancias GPS en tus zonas de entrenamiento',
      goal: gymDaysReq,
      unit: 'visitas GPS'
    },
    {
      id: 'wq4',
      title: `Dominio de la Procrastinación: Terminar ${1 + Math.floor(tierIndex / 2)} proyecto(s) o tarea(s) postergadas`,
      skill: 'wil',
      xp: 125 + tierIndex * 12,
      coins: 10,
      mode: 'manual',
      goal: 1 + Math.floor(tierIndex / 2),
      unit: 'meta(s)'
    },
    {
      id: 'wq5',
      title: `Erudición Profunda: Completar ${readBlocksReq} bloques de lectura de 15m en la semana`,
      skill: 'wil',
      xp: 140 + tierIndex * 15,
      coins: 12,
      mode: 'auto',
      autoTriggerLabel: 'Automática al completar ciclos de 15 minutos en el Grimorio PDF',
      goal: readBlocksReq,
      unit: 'ciclos 15m'
    },
    {
      id: 'wq6',
      title: `Vínculos Reales: Hacer un nuevo amigo o liderar ${1 + Math.floor(tierIndex / 3)} sesión(es) social/comunidad`,
      skill: 'wil',
      xp: 135 + tierIndex * 12,
      coins: 11,
      mode: 'manual',
      goal: 1 + Math.floor(tierIndex / 3),
      unit: 'meta social'
    }
  ];

  return baseWeekly.map(wq => {
    const prev = currentProgressMap[wq.id] || { progress: 1, completed: false };
    const prog = Math.min(wq.goal, prev.progress);
    return {
      ...wq,
      progress: prog,
      completed: prev.completed || prog >= wq.goal
    };
  });
}

