function generateHybridChallenge(mode = 'ram') {
  const archetypes = [
    () => {
      const items = [
        ['un Caballero de la Muerte', 'un Nigromante', 'un Esqueleto Guerrero'],
        ['un Lobo Fenrir', 'un Espíritu de Luz', 'un Cáliz de Maná'],
        ['un Gólem de Fuego', 'un Pergamino Antiguo', 'un Elemental de Hielo']
      ][Math.floor(Math.random() * 3)];
      return {
        id: 'dyn_' + Date.now() + Math.random(),
        category: mode === 'cloud' ? '🌐 Cloud IA • Cruce Estratégico' : '⚡ Motor RAM • Lógica de Cruce',
        difficulty: 'Media',
        xp: 75,
        coins: 3,
        skill: 'int',
        isDynamic: true,
        sourceMode: mode,
        question: `Debes cruzar un portal dimensional llevando ${items[0]}, ${items[1]} y ${items[2]}. Solo puedes llevar uno contigo en cada viaje. Si dejas solos a ${items[0]} con ${items[1]}, el primero consume al segundo; si dejas a ${items[1]} con ${items[2]}, el segundo se destruye. ¿Cuál es el mínimo de viajes para cruzar todo?`,
        options: [
          '7 viajes en total (llevando primero al elemento central y trayéndolo de vuelta en el paso intermedio)',
          '5 viajes en total sin regresar ninguno',
          '9 viajes dejando siempre dos juntos',
          'Es imposible sin otro invocador'
        ],
        correctIndex: 0,
        hint: `El elemento en conflicto con ambos es ${items[1]}. Debe ser el primero en cruzar y luego regresar contigo en el paso intermedio.`,
        explanation: `¡7 viajes! Llevas ${items[1]} (1), vuelves solo (2), llevas ${items[0]} (3), regresas con ${items[1]} (4), dejas ${items[1]} y llevas ${items[2]} (5), vuelves solo (6) y finalmente cruzas con ${items[1]} (7).`
      };
    },
    () => {
      const pairs = [
        { plain: 'MAGIA', shift: 1, cipher: 'NBHJB', topic: 'el poder supremo' },
        { plain: 'TRONO', shift: 1, cipher: 'USPOP', topic: 'la sala de Nazarick' },
        { plain: 'RUNAS', shift: 1, cipher: 'SVOBT', topic: 'la escritura secreta' },
        { plain: 'SABIO', shift: 1, cipher: 'TBCJP', topic: 'el conocimiento arcano' }
      ];
      const pick = pairs[Math.floor(Math.random() * pairs.length)];
      const distractors = pairs.filter(p => p.plain !== pick.plain).map(p => p.plain);
      const opts = [
        { val: pick.plain, correct: true },
        { val: distractors[0], correct: false },
        { val: distractors[1], correct: false },
        { val: distractors[2], correct: false }
      ].sort(() => Math.random() - 0.5);

      return {
        id: 'dyn_' + Date.now() + Math.random(),
        category: mode === 'cloud' ? '🌐 Cloud IA • Criptograma Arcano' : '⚡ Motor RAM • Desencriptación',
        difficulty: 'Media',
        xp: 80,
        coins: 3,
        skill: 'int',
        isDynamic: true,
        sourceMode: mode,
        question: `Descubriste un pergamino cifrado sobre ${pick.topic}: "${pick.cipher}". Cada letra fue desplazada +1 posición hacia adelante en el abecedario (A→B, B→C...). Si retrocedes cada letra una posición, ¿qué palabra oculta descubres?`,
        options: opts.map(o => o.val),
        correctIndex: opts.findIndex(o => o.correct),
        hint: `Toma la primera letra de "${pick.cipher}" (${pick.cipher[0]}) y busca la letra inmediatamente anterior en el abecedario.`,
        explanation: `Al retroceder una posición cada letra de ${pick.cipher}, se revela la palabra "${pick.plain}".`
      };
    }
  ];

  const pick = archetypes[Math.floor(Math.random() * archetypes.length)];
  return pick();
}

